@Injectable({ providedIn: 'root' })
export class FlagPreloading implements PreloadingStrategy {
  preload(route: Route, load: () => Observable<unknown>) {
    const slow = (navigator as any).connection?.saveData;
    return route.data?.['preload'] && !slow ? load() : of(null);
  }
}

provideRouter(routes, withPreloading(FlagPreloading));

private router = inject(Router);
loading = toSignal(
  this.router.events.pipe(
    filter(e => e instanceof NavigationStart || e instanceof NavigationEnd
             || e instanceof NavigationCancel || e instanceof NavigationError),
    map(e => e instanceof NavigationStart),
  ),
  { initialValue: false },
);

