export class UpdateService {
  constructor() {
    inject(SwUpdate).versionUpdates
      .pipe(filter((e): e is VersionReadyEvent => e.type === 'VERSION_READY'), takeUntilDestroyed())
      .subscribe(() => {
        if (confirm('Dostępna nowa wersja. Przeładować?')) document.location.reload();
      });
  }
}

let refresh$: Observable<string> | null = null;

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const auth = inject(AuthService);
  const withToken = (t: string) => req.clone({ setHeaders: { Authorization: `Bearer ${t}` } });
  return next(withToken(auth.token())).pipe(
    catchError(err => {
      if (err.status !== 401 || req.url.includes('/auth/')) return throwError(() => err);
      refresh$ ??= auth.refresh().pipe(finalize(() => (refresh$ = null)), shareReplay(1));
      return refresh$.pipe(switchMap(t => next(withToken(t))));
    }),
  );
};

